/**
 * Procedural-sky chunk — CODE-SPLIT.
 *
 * This is a REGISTERED CHUNK MANIFEST MODULE (see MANIFEST_MODULES in
 * tooling/check-shader-imports.mjs, `chunk: true` + ALLOWLIST) — the ONLY legal
 * import site for `ShaderMaterial` (a `@babylonjs/core/Materials/**` class). It
 * is loaded EXCLUSIVELY via dynamic `import()` from applyEnvironment.ts, ONLY
 * when a world's background is a `lite-procedural-sky` (lint rule 3: a static
 * import anywhere would pull ShaderMaterial into the main bundle and blow the
 * bundle budget — a world without a procedural sky never pays for it; the e2e
 * asserts BOTH directions).
 *
 * NOT `SkyMaterial` (Preetham atmospheric scattering). VEML's lite sky is a
 * gradient/day-night model with celestial bodies (ground/horizon/day+night
 * colors + sun/moon/stars/clouds driven by a sun light). A gradient
 * ShaderMaterial CONSUMES the authored ground/horizon/sun colors; Preetham
 * ignores all of them. The shader is
 * authored INLINE (the source is bundled here as strings), so there is NO
 * prebuilt Babylon shader module to side-effect-import and NO vite optimizeDeps
 * mirror entry — this chunk parallels audioChunk (a registered manifest module
 * with zero shader-mirror entries).
 *
 * WGSL-NATIVE ON WEBGPU. `bootstrap.ts` selects WebGPU FIRST
 * on desktop. A GLSL `ShaderMaterial` is NOT natively consumable by WebGPU —
 * Babylon would lazily transpile GLSL→WGSL via `prepareGlslangAndTintAsync()`,
 * which FETCHES twgsl+glslang WASM from `https://cdn.babylonjs.com` (an
 * off-origin fetch the app deliberately avoids — it stays same-origin; blocked
 * under a same-origin CSP → blank sky). To stay same-origin AND WGSL-native,
 * this chunk authors the shader in BOTH languages and selects by engine kind
 * (`selectSkyShaderSources`): GLSL for WebGL2, WGSL for WebGPU (with
 * `shaderLanguage: ShaderLanguage.WGSL`). This is what Babylon's own native
 * materials do (`ShadersWGSL/*` on WebGPU). The two sources are kept in sync
 * (same uniforms, same gradient + sun-disc math) and the selection is unit-
 * tested (engineKind → shaderLanguage + source). No transpiler, no CDN fetch on
 * ANY engine. The one failure class the manifest does NOT guard for an inline
 * material is a shader COMPILE error (a typo → blank sky, which headless e2e
 * cannot red-green by pixels): the analogue guard is the `isReady()`
 * material-readiness flag, surfaced on the observability hook and asserted in
 * the e2e.
 *
 * Fidelity: the CORE sky (ground→horizon→zenith day
 * gradient + a sun disc bound to sun-entity-tag) renders; the moon, stars
 * (procedural + texture / star-texture-uri), clouds (clouds-texture-uri +
 * animation), the day/night-cycle animation (night colors + time-driven blend),
 * and the horizon-saturation / sunset fine-tuning are parsed but NOT rendered.
 * Do not add them here — the chunk stays a gradient + sun disc.
 *
 * The dome mesh is `isPickable=false` and is NEVER registered with the
 * EntityRegistry, so it is non-walkable BY CONSTRUCTION (`walkableMeshes()`
 * returns registry-owned meshes only; the grounding probe filters to that set —
 * the "stuck at y=500 on the PhotoDome" bug cannot recur). `infiniteDistance`
 * keeps the dome centered on the camera, so the sky never parallaxes.
 */
import { ShaderMaterial } from '@babylonjs/core/Materials/shaderMaterial';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { CreateSphere } from '@babylonjs/core/Meshes/Builders/sphereBuilder';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { ProceduralSkyConfig } from './skyConfig';

const DEG_TO_RAD = Math.PI / 180;
/** Dome radius — large enough to enclose any world (same order as the PhotoDome). */
const DOME_DIAMETER = 2000;

// ---- GLSL (WebGL2 floor) ----
const VERTEX_SOURCE_GLSL = `
precision highp float;
attribute vec3 position;
uniform mat4 worldViewProjection;
varying vec3 vDir;
void main(void) {
  vDir = normalize(position);
  gl_Position = worldViewProjection * vec4(position, 1.0);
}`;

// Ground->horizon->zenith gradient (day colors) + a sun disc positioned by the
// bound sun light. y in [-1,1]: +1 zenith, 0 horizon, -1 straight down.
const FRAGMENT_SOURCE_GLSL = `
precision highp float;
varying vec3 vDir;
uniform vec3 groundColor;
uniform vec3 horizonColor;
uniform vec3 skyColor;
uniform vec3 sunColor;
uniform vec3 sunDirection;
uniform float sunCosInner;
uniform float sunCosOuter;
uniform float groundEnabled;
uniform float sunEnabled;
uniform float horizonSkyBlend;
uniform float groundFadeAmount;
void main(void) {
  vec3 dir = normalize(vDir);
  float y = dir.y;
  vec3 col;
  if (y >= 0.0) {
    float t = pow(clamp(y, 0.0, 1.0), 1.0 / max(horizonSkyBlend, 0.001));
    col = mix(horizonColor, skyColor, t);
  } else {
    float g = clamp(-y / max(groundFadeAmount, 0.001), 0.0, 1.0);
    col = (groundEnabled > 0.5) ? mix(horizonColor, groundColor, g) : horizonColor;
  }
  if (sunEnabled > 0.5) {
    float d = dot(dir, normalize(sunDirection));
    float disc = smoothstep(sunCosOuter, sunCosInner, d);
    col = mix(col, sunColor, disc);
  }
  gl_FragColor = vec4(col, 1.0);
}`;

// ---- WGSL (WebGPU path) — the SAME gradient + sun-disc math, in Babylon's
// WGSL ShaderMaterial dialect (attribute/uniform/varying decls; uniforms read
// via `uniforms.*`, varyings written via `vertexOutputs.*` / read via
// `input.*`; entry points `@vertex`/`@fragment`). Kept in lockstep with the
// GLSL above so the two engines render identically. Authoring WGSL here is why
// WebGPU needs NO GLSL→WGSL transpiler and makes NO cdn.babylonjs.com fetch. ----
const VERTEX_SOURCE_WGSL = `
attribute position: vec3f;
uniform worldViewProjection: mat4x4f;
varying vDir: vec3f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  vertexOutputs.vDir = normalize(vertexInputs.position);
  vertexOutputs.position = uniforms.worldViewProjection * vec4f(vertexInputs.position, 1.0);
}`;

const FRAGMENT_SOURCE_WGSL = `
varying vDir: vec3f;
uniform groundColor: vec3f;
uniform horizonColor: vec3f;
uniform skyColor: vec3f;
uniform sunColor: vec3f;
uniform sunDirection: vec3f;
uniform sunCosInner: f32;
uniform sunCosOuter: f32;
uniform groundEnabled: f32;
uniform sunEnabled: f32;
uniform horizonSkyBlend: f32;
uniform groundFadeAmount: f32;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  var dir: vec3f = normalize(input.vDir);
  var y: f32 = dir.y;
  var col: vec3f = uniforms.horizonColor;
  if (y >= 0.0) {
    var t: f32 = pow(clamp(y, 0.0, 1.0), 1.0 / max(uniforms.horizonSkyBlend, 0.001));
    col = mix(uniforms.horizonColor, uniforms.skyColor, t);
  } else {
    var g: f32 = clamp(-y / max(uniforms.groundFadeAmount, 0.001), 0.0, 1.0);
    if (uniforms.groundEnabled > 0.5) {
      col = mix(uniforms.horizonColor, uniforms.groundColor, g);
    } else {
      col = uniforms.horizonColor;
    }
  }
  if (uniforms.sunEnabled > 0.5) {
    var dd: f32 = dot(dir, normalize(uniforms.sunDirection));
    var disc: f32 = smoothstep(uniforms.sunCosOuter, uniforms.sunCosInner, dd);
    col = mix(col, uniforms.sunColor, disc);
  }
  fragmentOutputs.color = vec4f(col, 1.0);
}`;

/** The vertex/fragment source + shader language for a given engine kind. */
export interface SkyShaderSources {
  shaderLanguage: ShaderLanguage;
  vertexSource: string;
  fragmentSource: string;
}

/**
 * Select the sky shader source + language by engine kind. WebGPU consumes WGSL
 * NATIVELY (no GLSL→WGSL transpiler, no cdn.babylonjs.com fetch);
 * every other engine (the WebGL2 floor) takes GLSL. Pure + exported so the
 * selection is unit-tested without a live GPU.
 */
export function selectSkyShaderSources(engineKind?: string): SkyShaderSources {
  if (engineKind === 'webgpu') {
    return {
      shaderLanguage: ShaderLanguage.WGSL,
      vertexSource: VERTEX_SOURCE_WGSL,
      fragmentSource: FRAGMENT_SOURCE_WGSL,
    };
  }
  return {
    shaderLanguage: ShaderLanguage.GLSL,
    vertexSource: VERTEX_SOURCE_GLSL,
    fragmentSource: FRAGMENT_SOURCE_GLSL,
  };
}

export interface ProceduralSkyHandle {
  /** isPickable=false on the dome mesh (idempotent; belt-and-suspenders — the
   * dome is also never registered → never walkable). */
  setPickableFalse(): void;
  /** Point the sky's sun disc toward `skyDirection` (the direction FROM the
   * viewer TOWARD the sun in the sky). Called at bind and per-frame. */
  setSunDirection(skyDirection: Vector3): void;
  /** True once the ShaderMaterial's effect has compiled — the GLSL-compile
   * guard (a shader typo makes this false; asserted in e2e). Never throws. */
  isReady(): boolean;
  /** Dispose the dome mesh + material (churn-critical on a reused scene). */
  dispose(): void;
}

export type ProceduralSkyModule = {
  createProceduralSky(
    config: ProceduralSkyConfig,
    scene: Scene,
    engineKind?: string,
  ): ProceduralSkyHandle;
};

/**
 * Build the inverted-sphere sky dome + its gradient/sun-disc ShaderMaterial and
 * push the config as uniforms. The sun disc starts at a default direction
 * (upper sky); `setSunDirection` re-points it once the sun light binds.
 *
 * `engineKind` selects the shader language: WGSL on WebGPU (native — no CDN
 * transpiler), GLSL on the WebGL2 floor. Defaults to GLSL when unspecified.
 */
export function createProceduralSky(
  config: ProceduralSkyConfig,
  scene: Scene,
  engineKind?: string,
): ProceduralSkyHandle {
  const sources = selectSkyShaderSources(engineKind);
  const mesh = CreateSphere(
    'proceduralSkyDome',
    { diameter: DOME_DIAMETER, segments: 24, sideOrientation: Mesh.BACKSIDE },
    scene,
  );
  mesh.infiniteDistance = true; // SkySphereFollower equivalent (camera-centered)
  mesh.applyFog = false;
  mesh.isPickable = false;
  mesh.renderingGroupId = 0;

  const material = new ShaderMaterial(
    'proceduralSkyMaterial',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: sources.fragmentSource },
    {
      attributes: ['position'],
      uniforms: [
        'worldViewProjection',
        'groundColor',
        'horizonColor',
        'skyColor',
        'sunColor',
        'sunDirection',
        'sunCosInner',
        'sunCosOuter',
        'groundEnabled',
        'sunEnabled',
        'horizonSkyBlend',
        'groundFadeAmount',
      ],
      shaderLanguage: sources.shaderLanguage,
    },
  );
  material.backFaceCulling = false;
  material.disableDepthWrite = true; // the dome never occludes world geometry

  const c3 = (c: { r: number; g: number; b: number }): Color3 => new Color3(c.r, c.g, c.b);
  material.setColor3('groundColor', c3(config.groundColor));
  material.setColor3('horizonColor', c3(config.horizonColor));
  material.setColor3('skyColor', c3(config.skyColor));
  material.setColor3('sunColor', c3(config.sunColor));
  material.setFloat('groundEnabled', config.groundEnabled ? 1 : 0);
  material.setFloat('sunEnabled', config.sunEnabled ? 1 : 0);
  material.setFloat('horizonSkyBlend', config.horizonSkyBlend);
  material.setFloat('groundFadeAmount', config.groundFadeAmount);
  // Angular size → cosine thresholds for the smoothstep disc edge. sun-diameter
  // is an angular diameter in degrees; the exact disc size is an
  // approximation — the conformance-bearing behavior is
  // that the disc tracks the bound sun's direction.
  const radiusRad = Math.max(config.sunDiameter, 0.1) * DEG_TO_RAD;
  material.setFloat('sunCosInner', Math.cos(radiusRad * 0.5));
  material.setFloat('sunCosOuter', Math.cos(radiusRad));

  mesh.material = material;

  // Default sun direction (upper sky) so the defaults-only / unbound-sun path
  // still renders a sensible sun (the missing-sun fallback).
  const sunDir = new Vector3(0.3, 0.6, 0.3).normalize();
  material.setVector3('sunDirection', sunDir);

  return {
    setPickableFalse(): void {
      mesh.isPickable = false;
    },
    setSunDirection(skyDirection: Vector3): void {
      const d = skyDirection.clone().normalize();
      material.setVector3('sunDirection', d);
    },
    isReady(): boolean {
      return material.isReady(mesh);
    },
    dispose(): void {
      mesh.dispose(false, false);
      material.dispose();
    },
  };
}
